
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { appwrite } from '../../services/supabaseClient';
import { Heart } from 'lucide-react';

export default function Register() {
  const navigate = useNavigate();
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const base = import.meta.env.BASE_URL || '/';
  const authBgImages = [
    `${base}hero-images/young-wedding-couple-enjoying-romantic-moments.jpg`,
  ];
  const [bgIndex, setBgIndex] = useState(0);
  useEffect(() => {
    authBgImages.forEach((s) => { const i = new Image(); i.src = s; });
    return () => {};
  }, []);

  const handleGoogleSignIn = async () => {
    setError('');
    setLoading(true);
    try {
      await appwrite.account.createOAuth2Session('google', `${window.location.origin}/onboarding`, `${window.location.origin}/`);
      setLoading(false);
    } catch (error) {
      let message = 'Google sign-up failed';
      if (error && typeof error === 'object' && 'message' in error) {
        message = (error as any).message;
      }
      setError(message);
      setLoading(false);
    }
    // On success, Appwrite will redirect and handle session
  };

  return (
    <div className="min-h-screen flex items-center justify-center px-4" style={{ backgroundImage: `url(${authBgImages[bgIndex]})`, backgroundSize: 'cover', backgroundPosition: 'center' }}>
      <div className="max-w-md w-full">
        <div className="text-center mb-8">
          <div className="text-left mb-4">
            <button onClick={() => navigate('/')} className="text-lg text-white font-medium hover:underline">← Back to Home</button>
          </div>
          <div className="flex justify-center mb-4">
            <div className="bg-primary-500 text-white p-4 rounded-full">
              <Heart className="w-12 h-12" />
            </div>
          </div>
          <h1 className="text-4xl font-bold text-white mb-2">Vivaha</h1>
          <p className="text-white font-medium">Plan your wedding like a pro</p>
        </div>

        <div className="bg-white rounded-2xl shadow-xl p-8">
          {error && (
            <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm mb-4">
              {error}
            </div>
          )}
          <button
            onClick={handleGoogleSignIn}
            disabled={loading}
            className="w-full bg-primary-500 hover:bg-primary-600 text-white font-medium py-3 rounded-lg transition disabled:opacity-50 flex items-center justify-center gap-2"
          >
            <img src="https://www.svgrepo.com/show/475656/google-color.svg" alt="Google" className="w-6 h-6" />
            {'Sign up with Google'}
          </button>
          <div className="mt-3 text-center text-xs text-gray-500 font-medium">
            Sign in is done through our authenticator
          </div>
          <p className="mt-6 text-center text-sm text-gray-600">
            Already have an account?{' '}
            <button
              onClick={() => navigate('/login')}
              className="text-primary-500 hover:text-primary-600 font-medium"
            >
              Log in
            </button>
          </p>
        </div>
      </div>
    </div>
  );
}
