import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
import { appwrite } from '../services/supabaseClient';

interface OnboardingData {
	role: string;
	weddingStyle: string;
	topPriority?: string[];
	estimatedBudget?: number;
	guestCount?: number;
	weddingDate?: string;
	weddingTime?: string;
	weddingCity?: string;
	weddingState?: string;
	weddingCountry?: string;
	isReligious?: boolean;
	ceremonyType?: string;
	goals?: string;
	wantsBachelorParty?: boolean;
	plannerData?: Record<string, any>;
	[key: string]: any;
}

interface Budget {
	_id: string;
	userId: string;
	title: string;
	totalBudget: number;
	spent: number;
	remaining: number;
	expenses: any[];
	[key: string]: any;
}

interface Registry {
	_id: string;
	userId: string;
	name: string;
	items: any[];
	[key: string]: any;
}

interface User {
	_id: string;
	email: string;
	name?: string;
	isAdmin?: boolean;
	onboardingCompleted?: boolean;
	[key: string]: any;
}

interface AppContextType {
	user: User | null;
	isAuthenticated: boolean;
	isLoading: boolean;
	onboardingData: OnboardingData | null;
	setOnboardingData: (data: OnboardingData) => void;
	saveOnboarding: (data: OnboardingData) => Promise<void>;
	hasCompletedOnboarding: boolean;
	budgets: Budget[];
	fetchBudgets: () => Promise<void>;
	updateBudget: (id: string, data: any) => Promise<void>;
	deleteBudget: (id: string) => Promise<void>;
	registries: Registry[];
	fetchRegistries: () => Promise<void>;
	updateRegistry: (id: string, data: any) => Promise<void>;
	expenses: any[];
	fetchExpenses: (budgetId: string) => Promise<void>;
	addExpense: (budgetId: string, expense: any) => Promise<void>;
	settleExpense: (expenseId: string) => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider = ({ children }: { children: React.ReactNode }) => {
		// Appwrite DB IDs (replace with your actual IDs)
		const databaseId = 'vivaha_db';
		const collectionId = 'onboarding';
	const [user, setUser] = useState<User | null>(null);
	const [isAuthenticated, setIsAuthenticated] = useState(false);
	const [isLoading, setIsLoading] = useState(true);
	const [onboardingData, setOnboardingData] = useState<OnboardingData | null>(null);
	const [hasCompletedOnboarding, setHasCompletedOnboarding] = useState(false);
	const [budgets, setBudgets] = useState<Budget[]>([]);
	const [registries, setRegistries] = useState<Registry[]>([]);
	const [expenses, setExpenses] = useState<any[]>([]);

	 // Appwrite authentication logic
	const fetchUser = useCallback(async () => {
		try {
			setIsLoading(true);
			const account = appwrite.account;
			const userData = await account.get();
			setUser({ _id: userData.$id, email: userData.email, name: userData.name || '', isAdmin: false });
			setIsAuthenticated(true);
			// Fetch onboarding data for user
			try {
				const onboardingDoc = await appwrite.databases.getDocument(databaseId, collectionId, userData.$id);
				// Map Appwrite Document to OnboardingData shape
				const mappedOnboarding: OnboardingData = {
					role: onboardingDoc.role || '',
					weddingStyle: onboardingDoc.weddingStyle || '',
					topPriority: onboardingDoc.topPriority || [],
					estimatedBudget: onboardingDoc.estimatedBudget,
					guestCount: onboardingDoc.guestCount,
					weddingDate: onboardingDoc.weddingDate,
					weddingTime: onboardingDoc.weddingTime,
					weddingCity: onboardingDoc.weddingCity,
					weddingState: onboardingDoc.weddingState,
					weddingCountry: onboardingDoc.weddingCountry,
					isReligious: onboardingDoc.isReligious,
					ceremonyType: onboardingDoc.ceremonyType,
					goals: onboardingDoc.goals,
					wantsBachelorParty: onboardingDoc.wantsBachelorParty,
					plannerData: onboardingDoc.plannerData,
					...onboardingDoc // include any extra fields
				};
				setOnboardingData(mappedOnboarding);
				setHasCompletedOnboarding(!!mappedOnboarding.role && !!mappedOnboarding.weddingStyle);
			} catch (err) {
				setOnboardingData(null);
				setHasCompletedOnboarding(false);
			}
			setIsLoading(false);
		} catch (error) {
			setUser(null);
			setIsAuthenticated(false);
			setIsLoading(false);
		}
	}, []);

	 useEffect(() => {
		 fetchUser();
	 }, [fetchUser]);

	 // Replace onboarding, budgets, registries, expenses logic with Appwrite DB calls as needed
	 // ...existing code...
	const saveOnboarding = useCallback(async (data: OnboardingData) => {
		if (!user?._id) throw new Error('User not authenticated');
		// Save onboarding data to Appwrite DB
		try {
			const docId = user._id;
			try {
				await appwrite.databases.updateDocument(databaseId, collectionId, docId, { ...data, user_id: user._id });
			} catch (err) {
				await appwrite.databases.createDocument(databaseId, collectionId, docId, { ...data, user_id: user._id });
			}
			setOnboardingData(data);
			setHasCompletedOnboarding(true);
		} catch (error) {
			throw new Error('Failed to save onboarding');
		}
	}, [user]);

	const fetchBudgets = useCallback(async () => {
		if (!user?._id) return;
		// Replace with Appwrite DB logic
		// Example: const budgets = await appwrite.databases.listDocuments('databaseId', 'budgets', [user._id]);
		setBudgets([]); // Placeholder
	}, [user]);

	const updateBudget = useCallback(async (id: string, data: any) => {
		// Replace with Appwrite DB logic
		// Example: await appwrite.databases.updateDocument('databaseId', 'budgets', id, data);
		await fetchBudgets();
	}, [fetchBudgets]);

	const deleteBudget = useCallback(async (id: string) => {
		// Replace with Appwrite DB logic
		// Example: await appwrite.databases.deleteDocument('databaseId', 'budgets', id);
		await fetchBudgets();
	}, [fetchBudgets]);

	const fetchRegistries = useCallback(async () => {
		if (!user?._id) return;
		// Replace with Appwrite DB logic
		setRegistries([]); // Placeholder
	}, [user]);

	const updateRegistry = useCallback(async (id: string, data: any) => {
		// Replace with Appwrite DB logic
		await fetchRegistries();
	}, [fetchRegistries]);

	const fetchExpenses = useCallback(async (budgetId: string) => {
		// Replace with Appwrite DB logic
		setExpenses([]); // Placeholder
	}, []);

	const addExpense = useCallback(async (budgetId: string, expense: any) => {
		// Replace with Appwrite DB logic
		await fetchExpenses(budgetId);
	}, [fetchExpenses]);

	const settleExpense = useCallback(async (expenseId: string) => {
		// Replace with Appwrite DB logic
		await fetchBudgets();
	}, [fetchBudgets]);

	// Appwrite user/session logic handled in fetchUser/useEffect above

	const value: AppContextType = {
		user,
		isAuthenticated,
		isLoading,
		onboardingData,
		setOnboardingData,
		saveOnboarding,
		hasCompletedOnboarding,
		budgets,
		fetchBudgets,
		updateBudget,
		deleteBudget,
		registries,
		fetchRegistries,
		updateRegistry,
		expenses,
		fetchExpenses,
		addExpense,
		settleExpense,
	};
	return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
};

export const useApp = () => {
	const context = useContext(AppContext);
	if (context === undefined) {
		throw new Error('useApp must be used within an AppProvider');
	}
	return context;
};
