
import React, { ReactNode } from 'react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorCount: number;
}

export class ErrorBoundary extends React.Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null, errorCount: 0 };
  }

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    // Enhanced logging for debugging
    console.error('Error caught by boundary:', error, errorInfo);
    if (typeof window !== 'undefined') {
      try {
        fetch('https://vivahaplan.com/error-log', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            message: error.message,
            stack: error.stack,
            info: errorInfo,
            url: window.location.href,
            userAgent: navigator.userAgent
          })
        });
      } catch (e) {
        // Ignore logging errors
      }
    }
    this.setState(prev => ({ errorCount: prev.errorCount + 1 }));
  }
  handleRetry = () => {
    this.setState({ hasError: false, error: null });
  };

  render() {
    if (this.state.hasError) {
      return (
        <div className="flex items-center justify-center min-h-96 p-6">
          <div className="bg-red-50 border border-red-200 rounded-lg p-6 max-w-2xl text-center">
            <div className="text-4xl mb-3">⚠️</div>
            <h2 className="text-xl font-bold text-red-900 mb-2">Oops, something went wrong</h2>
            <p className="text-red-700 mb-4 text-sm">{this.state.error?.message || 'An unexpected error occurred'}</p>
            {this.state.error?.stack && (
              <pre className="bg-gray-100 text-xs text-left p-2 rounded mb-2 overflow-x-auto max-h-48 whitespace-pre-wrap break-all">
                {this.state.error.stack}
              </pre>
            )}
            <p className="text-gray-600 text-xs mb-4">
              Error attempts: {this.state.errorCount}
            </p>
            <div className="flex gap-2 justify-center">
              <button
                onClick={this.handleRetry}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition"
              >
                Try Again
              </button>
              <button
                onClick={() => window.location.href = '/dashboard'}
                className="px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition"
              >
                Go to Dashboard
              </button>
            </div>
          </div>
        </div>
      );
    }
      const { error } = this.state;
      let errorDetails = '';
      if (error) {
        errorDetails = Object.entries(error).map(([k, v]) => `${k}: ${String(v)}`).join('\n');
      }
      const isGeneric = !error?.message && !error?.stack && !errorDetails;
      return (
        <div className="flex items-center justify-center min-h-96 p-6">
          <div className="bg-red-50 border border-red-200 rounded-lg p-6 max-w-2xl text-left">
            <div className="text-4xl mb-3">⚠️</div>
            <h2 className="text-xl font-bold text-red-900 mb-2">Oops, something went wrong</h2>
            <p className="text-red-700 mb-2 text-sm">{error?.name || 'Error'}: {error?.message || 'An unexpected error occurred'}</p>
            {isGeneric && (
              <div className="bg-yellow-100 text-yellow-800 text-xs p-2 rounded mb-2">
                This error has no details. It may be caused by a build, environment, or minification issue. Try running a non-minified build or check your environment variables.
              </div>
            )}
            {errorDetails && (
              <pre className="bg-gray-100 text-xs p-2 rounded mb-2 overflow-x-auto max-h-32 whitespace-pre-wrap break-all">
                {errorDetails}
              </pre>
            )}
            {error?.stack && (
              <pre className="bg-gray-100 text-xs p-2 rounded mb-2 overflow-x-auto max-h-48 whitespace-pre-wrap break-all">
                {error.stack}
              </pre>
            )}
            <p className="text-xs text-gray-600 mb-1">URL: {typeof window !== 'undefined' ? window.location.href : ''}</p>
            <p className="text-xs text-gray-600 mb-4">User Agent: {typeof navigator !== 'undefined' ? navigator.userAgent : ''}</p>
            <p className="text-gray-600 text-xs mb-4">Error attempts: {this.state.errorCount}</p>
            <div className="flex gap-2 justify-center">
              <button
                onClick={this.handleRetry}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition"
              >
                Try Again
              </button>
              <button
                onClick={() => window.location.href = '/dashboard'}
                className="px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition"
              >
                Go to Dashboard
              </button>
            </div>
          </div>
        </div>
      );
    return this.props.children;
  }
}
